import java.util.Scanner;

public class Main {
    static final int N = 300010;
    static int n, K, mod;
    static int[][] dp = new int[N][20];
    static int[] cnt = new int[N], mx = new int[N];
    static int[] cj = new int[N], inv = new int[N];

    static int power(int x, int y) {
        int ret = 1;
        while (y > 0) {
            if ((y & 1) == 1) {
                ret = (int) ((long) ret * x % mod);
            }
            x = (int) ((long) x * x % mod);
            y >>= 1;
        }
        return ret;
    }

    static int C(int i, int j) {
        return (int) ((long) cj[i] * inv[j] % mod * inv[i - j] % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        K = sc.nextInt();
        mod = sc.nextInt();

        if ((n & 1) == 1) {
            System.out.println(power(K, n));
            sc.close();
            return;
        }

        cj[0] = 1;
        for (int i = 1; i <= n; i++) {
            cj[i] = (int) ((long) cj[i - 1] * i % mod);
        }

        inv[n] = power(cj[n], mod - 2);
        inv[0] = 1;
        for (int i = n - 1; i >= 1; i--) {
            inv[i] = (int) ((long) inv[i + 1] * (i + 1) % mod);
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= 18; j++) {
                if (((1 << j) & i) != 0) {
                    cnt[i]++;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 18; j >= 0; j--) {
                if (((1 << j) & i) != 0) {
                    mx[i] = 1 << j;
                    break;
                }
            }
        }

        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            if ((n & i) != i) continue;
            int now = i ^ mx[i];
            for (int k = now; k >= 0; k = (k - 1) & now) {
                int cur1 = k + mx[i];
                int cur2 = i ^ cur1;
                int up = Math.min(K - 1, cnt[cur2]);
                int tmp = C(i, cur1);
                for (int j = 0; j <= up; j++) {
                    dp[i][j + 1] = (int) ((dp[i][j + 1] + (long) dp[cur2][j] * tmp % mod) % mod);
                }
                if (k == 0) break;
            }
        }

        int ans = 0;
        int limit = Math.min(cnt[n], K);
        for (int j = 1; j <= limit; j++) {
            ans = (int) ((ans + (long) dp[n][j] * C(K, j) % mod * cj[j]) % mod);
        }
        ans = (power(K, n) - ans + mod) % mod;
        System.out.println(ans);
        sc.close();
    }
}
